    h = int(g.get("grid_height", 0) or 0)

    def xy(v, d=None):
        if isinstance(v, dict):
            x = v.get("x", v.get("col", v.get("c")))
            y = v.get("y", v.get("row", v.get("r")))
            if x is not None and y is not None:
